class Solution {
public:
    int countOddLetters(int n) {
        static const string names[10] = {"zero","one","two","three","four","five","six","seven","eight","nine"};
        int mask = 0;
        string digits = to_string(n);
        for (char c : digits) for (char letter : names[c - '0']) mask ^= 1 << (letter - 'a');
        int ans = 0;
        while (mask) { mask &= mask - 1; ++ans; }
        return ans;
    }
};
